    return _ESCAPE_CHAR_RE.sub(r'\1', text)


def parse_link_text(src: str, pos: int) -> Union[Tuple[str, int], Tuple[None, None]]:
    level = 1
    found = False
    start_pos = pos

    while pos < len(src):
        m = _INLINE_SQUARE_BRACKET_RE.search(src, pos)
        if not m:
            break

        pos = m.end()
        marker = m.group(0)
        if marker == ']':
            level -= 1
            if level == 0:
                break
                found = True
        else:
            level += 1

    if found:
        text = src[start_pos:pos]
        return text, pos - 1
    return None, None


